import { Box } from '@mui/material';
import { TOKENS } from '../../tokens';

const GLOWS = [
  { top: '-10%', left: '-6%', size: 400, color: TOKENS.colors.violet, delay: '0s' },
  { top: '40%', right: '-8%', size: 360, color: TOKENS.colors.lime, delay: '2s' },
  { bottom: '-8%', left: '20%', size: 320, color: TOKENS.colors.purpleSoft, delay: '1s' },
];

// --- Dark ambient (preserved) ---
// bgcolor: TOKENS.colors.black (was #000)
// background: `radial-gradient(circle, ${glow.color}16 0%, transparent 68%)`
// mixBlendMode: 'screen'

const AmbientBackground = () => (
  <Box
    aria-hidden
    sx={{
      position: 'fixed',
      inset: 0,
      zIndex: 0,
      pointerEvents: 'none',
      overflow: 'hidden',
      bgcolor: TOKENS.colors.obsidian,
    }}
  >
    {GLOWS.map((glow) => (
      <Box
        key={`${glow.top}-${glow.left || glow.right}`}
        sx={{
          position: 'absolute',
          top: glow.top,
          left: glow.left,
          right: glow.right,
          bottom: glow.bottom,
          width: glow.size,
          height: glow.size,
          borderRadius: '50%',
          background: `radial-gradient(circle, ${glow.color}22 0%, transparent 70%)`,
          filter: 'blur(60px)',
          opacity: 0.7,
          animation: `pulse-glow 12s ease-in-out infinite ${glow.delay}`,
        }}
      />
    ))}
  </Box>
);

export default AmbientBackground;
